"""Post-review feasibility census only; not a new significance test."""
import hashlib,itertools,json,random
from collections import defaultdict
from pathlib import Path
import analyze as a
ROOT=Path(__file__).resolve().parent

def census(pages):
    ts=a.dsl.tokens(pages);rows=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P':rows[t['line']].append(i)
    blocks=defaultdict(list)
    for row in rows.values():
        row.sort(key=lambda i:ts[i]['k']);blocks[(ts[row[0]]['page'],ts[row[0]]['n'])].append(row)
    mobile=set();active=[];examined=0
    for block in blocks.values():
        for ra,rb in itertools.combinations(block,2):
            examined+=1;m=a.Pair([ts[i]['w'] for i in ra],[ts[i]['w'] for i in rb])
            if m.states==1:continue
            active.append({'page':ts[ra[0]]['folio'],'rows':[ts[ra[0]]['lid'],ts[rb[0]]['lid']],
                           'n':ts[ra[0]]['n'],'states':m.states,'movable_columns':m.movable})
            for k in m.movable:
                for i in (ra[k],rb[k]):mobile.add((ts[i]['line'],ts[i]['k']))
    pairs=a.dsl._edge_length_pairs(a.dsl.select(ts,{'unit':['P'],'certain':True}))
    affected=sum((x['line'],x['k']) in mobile or (y['line'],y['k']) in mobile for x,y in pairs)
    # Rebuilding the fixed pairing after one feasible assignment must select the same rows.
    fixed,meta=a.build(ts);words=[t['w'] for t in ts]
    for ra,rb,m in fixed:
        x,y=m.assignment(m.states-1)
        for i,w in zip(ra,x):words[i]=w
        for i,w in zip(rb,y):words[i]=w
    sh=[dict(t,w=w) for t,w in zip(ts,words)];a.invariants(ts,sh,fixed)
    _,new_meta=a.build(sh)
    assert [(m['rows'],m['inventory_overlap'],m['states']) for m in meta]==[(m['rows'],m['inventory_overlap'],m['states']) for m in new_meta]
    return {'examined_row_pairs':examined,'active_row_pairs':len(active),'union_movable_word_positions':len(mobile),
            'union_affected_adjacent_pairs':affected,'adjacent_pairs':len(pairs),'active':active,
            'pairing_invariance_check':True}

if __name__=='__main__':
    plan={'phase':'Post-review feasibility census, specified after the fixed-pair primary result was seen.',
          'scope':'All unordered P-row pairs within same public page and exact token count, ZL and IT evaluation only.',
          'report':'Exact feasible assignments and union of affected positions at the observed layout. No new p-value. Do not multiply overlapping pair supports or claim this exhausts trades among three or more rows.'}
    (ROOT/'coverage-plan.json').write_text(json.dumps(plan,indent=2)+'\n',encoding='utf-8')
    out={'plan':plan,'results':{}}
    for ed in ('zl','it'):
        _,ev=a.corpus.split_pages('practice',ed);out['results'][ed]=census(ev);print(ed,out['results'][ed],flush=True)
    (ROOT/'coverage.json').write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8')

