"""Post-review exact closure under all admissible two-row moves, bounded cost."""
import itertools,json
from collections import defaultdict,deque
from pathlib import Path
import analyze as a
ROOT=Path(__file__).resolve().parent
PLAN={'phase':'Post-review feasibility extension after the all-pair census, not a new significance test.',
      'moves':'All exact balanced two-row assignments within same public page and original width, equal per-position lengths, fixed word multiset in each row and fixed unordered column word pairs for each move.',
      'max_layouts':1000,'report':'BFS enumerates the entire reachable component or explicitly reports truncation. Only ZL/IT manuscript practice evaluation. Does not cover irreducible trades involving three or more rows simultaneously. No confirmatory p-value.'}

def run(pages):
    ts=a.dsl.tokens(pages);rows=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P':rows[t['line']].append(i)
    blocks=defaultdict(list)
    for row in rows.values():
        row.sort(key=lambda i:ts[i]['k']);blocks[(ts[row[0]]['page'],ts[row[0]]['n'])].append(row)
    candidates=[(x,y) for block in blocks.values() for x,y in itertools.combinations(block,2)]
    first=tuple(t['w'] for t in ts);seen={first};queue=deque([first]);complete=True
    while queue and complete:
        state=queue.popleft();cur=[dict(t,w=w) for t,w in zip(ts,state)]
        for ra,rb in candidates:
            m=a.Pair([state[i] for i in ra],[state[i] for i in rb])
            if m.states==1:continue
            if m.states>1000:complete=False;break
            for rank in range(m.states):
                x,y=m.assignment(rank);target=list(state)
                for i,w in zip(ra,x):target[i]=w
                for i,w in zip(rb,y):target[i]=w
                target=tuple(target)
                if target in seen:continue
                if len(seen)>=1000:complete=False;break
                sh=[dict(t,w=w) for t,w in zip(ts,target)];a.invariants(cur,sh,[(ra,rb,m)])
                seen.add(target);queue.append(target)
    selected=a.dsl.select(ts,{'unit':['P'],'certain':True});pairs=a.dsl._edge_length_pairs(selected)
    changing={i for i in range(len(ts)) if any(layout[i]!=first[i] for layout in seen)}
    spots={(ts[i]['line'],ts[i]['k']) for i in changing}
    affected=sum((x['line'],x['k']) in spots or (y['line'],y['k']) in spots for x,y in pairs)
    values=[]
    for layout in seen:
        sh=[dict(t,w=w) for t,w in zip(ts,layout)]
        values.append(a.dsl.statistic({'edge_length_cmi':True},a.dsl.select(sh,{'unit':['P'],'certain':True}),sh))
    return {'complete_under_two_row_moves':complete,'reachable_layouts':len(seen),'changing_word_positions':len(changing),
            'affected_adjacent_pairs':affected,'adjacent_pairs':len(pairs),'statistic_values':sorted(values),
            'smallest_possible_exact_tail':1/len(seen) if complete else None,
            'interpretation':'Feasibility only; too little support for alpha.01 when fewer than100 states. No claim about multi-row irreducible cycles.'}

if __name__=='__main__':
    (ROOT/'closure-plan.json').write_text(json.dumps(PLAN,indent=2)+'\n',encoding='utf-8')
    result={'plan':PLAN,'results':{}}
    for ed in ('zl','it'):
        _,ev=a.corpus.split_pages('practice',ed);result['results'][ed]=run(ev);print(ed,result['results'][ed],flush=True)
    (ROOT/'closure.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')

